(4258040, 614672, 84736, '<td valign="top">Very cool - 8</td>', 'Very cool - 8', '2007-11-19 12:33:06.000000', NULL, 1),
(4258045, 614134, 84736, '<td valign="top">Wow, love the color and clarity - 9</td>', 'Wow, love the color and clarity - 9', '2007-11-19 12:35:33.000000', NULL, 1),
(4258054, 613989, 52472, '<td valign="top">10 for the brilliant and out of the box composition!</td>', '10 for the brilliant and out of the box composition!', '2007-11-19 12:46:18.000000', NULL, 1),
(4258060, 614453, 52472, '<td valign="top">That''s a picture worth of being hung on a wall, like an impressionistic painting. 10!</td>', 'That''s a picture worth of being hung on a wall, like an impressionistic painting. 10!', '2007-11-19 12:50:12.000000', NULL, 1),
(4258064, 614453, 56002, '<td valign="top">This is such a pleasant photo to view.  I love the color, love the angles at the window, love the 2d tree with it''s 3d branches.   All ''round pleasure.</td>', 'This is such a pleasant photo to view.  I love the color, love the angles at the window, love the 2d tree with it''s 3d branches.   All ''round pleasure.', '2007-11-19 12:52:04.000000', NULL, 1),
(4258067, 614688, 37444, '<td valign="top">Meets the challenge, but the image overall looks grainy. The bird is also leaving the frame, leading the viewer''s eye out. The pattern of the clouds, though beyond your control, adds nothing to the image.</td>', 'Meets the challenge, but the image overall looks grainy. The bird is also leaving the frame, leading the viewer''s eye out. The pattern of the clouds, though beyond your control, adds nothing to the image.', '2007-11-19 12:54:22.000000', NULL, 1),
(4258072, 612341, 37444, '<td valign="top">Though not what the viewer expects because such a boat is not moving very fast, to me it does meet the challenge. Drawing back and including more of the surrounding water would make it a bit better.</td>', 'Though not what the viewer expects because such a boat is not moving very fast, to me it does meet the challenge. Drawing back and including more of the surrounding water would make it a bit better.', '2007-11-19 12:56:10.000000', NULL, 1),
(4258074, 614710, 37444, '<td valign="top">Sadly it is out of focus and if not for the title, one might not even guess that this is a fish.</td>', 'Sadly it is out of focus and if not for the title, one might not even guess that this is a fish.', '2007-11-19 12:56:42.000000', NULL, 1),
(4258076, 614632, 37444, '<td valign="top">Beautifully captured, great composition, though the tree branches in the lower left are a bit distracting. 9</td>', 'Beautifully captured, great composition, though the tree branches in the lower left are a bit distracting. 9', '2007-11-19 12:57:37.000000', NULL, 1),
(4258079, 614458, 37444, '<td valign="top">I knew there would be these "splash" shots :) Captures stopped motion very well, but the lime just overpowers the image because of sheer size. Using a wedge would have helped here - or pulling back to allow room around the subject.</td>', 'I knew there would be these "splash" shots :) Captures stopped motion very well, but the lime just overpowers the image because of sheer size. Using a wedge would have helped here - or pulling back to allow room around the subject.', '2007-11-19 12:59:12.000000', NULL, 1),
(4258082, 614575, 37444, '<td valign="top">I had to look at this for a while to allow all the elements to reach my brain. This is a very creative shot. 8</td>', 'I had to look at this for a while to allow all the elements to reach my brain. This is a very creative shot. 8', '2007-11-19 13:00:11.000000', NULL, 1),
(4258083, 612566, 37444, '<td valign="top">Nah - they''re just playing. Great shot and love that eyeball! 8</td>', 'Nah - they''re just playing. Great shot and love that eyeball! 8', '2007-11-19 13:00:48.000000', NULL, 1),
(4258086, 614543, 37444, '<td valign="top">This is stopped motion, no doubt about it. The background is very distracting though.</td>', 'This is stopped motion, no doubt about it. The background is very distracting though.', '2007-11-19 13:01:24.000000', NULL, 1),
(4258088, 614598, 81783, '<td valign="top">love the model, but don''t see the Motion???</td>', 'love the model, but don''t see the Motion???', '2007-11-19 13:01:36.000000', NULL, 1),
(4258090, 614459, 37444, '<td valign="top">The image does not imply stopped motion as it looks like she is merely sitting.</td>', 'The image does not imply stopped motion as it looks like she is merely sitting.', '2007-11-19 13:02:02.000000', NULL, 1),
(4258092, 614618, 37444, '<td valign="top">If the title did not say "smoke", I would not know what this is.</td>', 'If the title did not say "smoke", I would not know what this is.', '2007-11-19 13:02:36.000000', NULL, 1),
