(4258096, 613799, 37444, '<td valign="top">Nice bokeh, leaves are well caught, but the leg does nothing for the image.</td>', 'Nice bokeh, leaves are well caught, but the leg does nothing for the image.', '2007-11-19 13:04:03.000000', NULL, 1),
(4258097, 614695, 23484, '<td valign="top">I''m giving you a ''1'' because I don''t like your choice!!!!!!</td>', 'I''m giving you a ''1'' because I don''t like your choice!!!!!!', '2007-11-19 13:04:08.000000', NULL, 1),
(4258098, 614616, 37444, '<td valign="top">You stopped motion! Even the background is not bad, but I suppose not seeing the person''s expression leaves something out of the story.</td>', 'You stopped motion! Even the background is not bad, but I suppose not seeing the person''s expression leaves something out of the story.', '2007-11-19 13:05:02.000000', NULL, 1),
(4258102, 614445, 23484, '<td valign="top">You did a good job at stopping the motion. This may have looked better if it were a little wider.</td>', 'You did a good job at stopping the motion. This may have looked better if it were a little wider.', '2007-11-19 13:06:07.000000', NULL, 1),
