(4258105, 614462, 23484, '<td valign="top">This is a very cool shot. I hope you don''t get punished for the stopped motion part.</td>', 'This is a very cool shot. I hope you don''t get punished for the stopped motion part.', '2007-11-19 13:08:27.000000', NULL, 1),
(4258107, 612859, 23484, '<td valign="top">Very neat shot. Almost looks like a bullet.</td>', 'Very neat shot. Almost looks like a bullet.', '2007-11-19 13:09:04.000000', NULL, 1),
(4258108, 614549, 37444, '<td valign="top">This is stretching the interp of the challenge too much. Feet moving yes, but the upper body really does not impart motion. Other than that minor technicality, the image is wonderful. Nicely processed and a nice story here with the umbrella in the boy''s hand. Rain expected? 7</td>', 'This is stretching the interp of the challenge too much. Feet moving yes, but the upper body really does not impart motion. Other than that minor technicality, the image is wonderful. Nicely processed and a nice story here with the umbrella in the boy''s hand. Rain expected? 7', '2007-11-19 13:09:41.000000', NULL, 1),
(4258110, 614563, 37444, '<td valign="top">I hope you did not throw this poor dog up in the air just for this shot. If he is used to it, that is one thing, but to terrify the poor thing for the sake of a challenge is low.</td>', 'I hope you did not throw this poor dog up in the air just for this shot. If he is used to it, that is one thing, but to terrify the poor thing for the sake of a challenge is low.', '2007-11-19 13:10:40.000000', NULL, 1),
(4258111, 614698, 23484, '<td valign="top">Very nice job on the stopped motion.</td>', 'Very nice job on the stopped motion.', '2007-11-19 13:10:41.000000', NULL, 1),
(4258112, 614649, 23484, '<td valign="top">Great stopped motion and neat silhouette. Well composed also.</td>', 'Great stopped motion and neat silhouette. Well composed also.', '2007-11-19 13:11:17.000000', NULL, 1),
(4258113, 614165, 37444, '<td valign="top">If it weren''t for the hair, one could not see stopped motion. But it is and it is a nice shot.</td>', 'If it weren''t for the hair, one could not see stopped motion. But it is and it is a nice shot.', '2007-11-19 13:11:20.000000', NULL, 1),
(4258114, 614708, 82814, '<td valign="top">Love the mood and the shadow/light contrasts.  Nicely done!</td>', 'Love the mood and the shadow/light contrasts.  Nicely done!', '2007-11-19 13:11:49.000000', NULL, 1),
(4258115, 614445, 37444, '<td valign="top">Absolutely wonderful. What makes this shot for me is the water splash in front of the bird. 10</td>', 'Absolutely wonderful. What makes this shot for me is the water splash in front of the bird. 10', '2007-11-19 13:11:59.000000', NULL, 1),
(4258117, 614149, 82814, '<td valign="top">Wonderful capture.  Hit the moment dead on.</td>', 'Wonderful capture.  Hit the moment dead on.', '2007-11-19 13:12:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
