(4258122, 614196, 23484, '<td valign="top">Excellent capture. The detail is fantastic for this type of shot.</td>', 'Excellent capture. The detail is fantastic for this type of shot.', '2007-11-19 13:13:36.000000', NULL, 1),
(4258124, 614515, 9462, '<td valign="top">This is the same kitty as Tuna Hunting?</td>', 'This is the same kitty as Tuna Hunting?', '2007-11-19 13:14:06.000000', NULL, 1),
(4258127, 614556, 23484, '<td valign="top">Very neat idea. The clouds in the background are a nice effect.</td>', 'Very neat idea. The clouds in the background are a nice effect.', '2007-11-19 13:14:37.000000', NULL, 1),
(4258137, 614672, 82814, '<td valign="top">I''m blown away by the timing of this image (forgive the pun)and the amount of time it must have taken to get this image with impecible clarity of the speeding bullet.  Superb, outstanding, fascinating, spectacular!  A 10 without question.  This takes the challenge to a whole new level.  If this isn''t the blue ribbon winner I''ll be very disappointed.</td>', 'I''m blown away by the timing of this image (forgive the pun)and the amount of time it must have taken to get this image with impecible clarity of the speeding bullet.  Superb, outstanding, fascinating, spectacular!  A 10 without question.  This takes the challenge to a whole new level.  If this isn''t the blue ribbon winner I''ll be very disappointed.', '2007-11-19 13:18:07.000000', NULL, 1),
(4258139, 614661, 82814, '<td valign="top">Exceptional image.  Well done.</td>', 'Exceptional image.  Well done.', '2007-11-19 13:18:42.000000', NULL, 1),
(4258140, 614626, 23484, '<td valign="top">This would have looked really cool with a panning motion.</td>', 'This would have looked really cool with a panning motion.', '2007-11-19 13:18:53.000000', NULL, 1),
(4258141, 613727, 37444, '<td valign="top">Guessing this is a studio setting. These kind of shots are not as difficult as capturing something as it happens - like wildlife - since you have the option of more than one take. Having said that, it is wonderfully done; a great stock photo!</td>', 'Guessing this is a studio setting. These kind of shots are not as difficult as capturing something as it happens - like wildlife - since you have the option of more than one take. Having said that, it is wonderfully done; a great stock photo!', '2007-11-19 13:19:07.000000', NULL, 1),
(4258143, 614468, 23484, '<td valign="top">Very nice job with the stark contrast and the silhouette.  The B&amp;W gives a nice effect.</td>', 'Very nice job with the stark contrast and the silhouette.  The B&W gives a nice effect.', '2007-11-19 13:19:36.000000', NULL, 1),
(4258144, 614216, 37444, '<td valign="top">Wonderfully captured and great expression on the boy.</td>', 'Wonderfully captured and great expression on the boy.', '2007-11-19 13:19:42.000000', NULL, 1),
(4258145, 613934, 23484, '<td valign="top">Very nice detail.</td>', 'Very nice detail.', '2007-11-19 13:19:59.000000', NULL, 1),
(4258146, 614584, 37444, '<td valign="top">Perfect! You got the ball as well! What a cute face too :) 10</td>', 'Perfect! You got the ball as well! What a cute face too :) 10', '2007-11-19 13:20:12.000000', NULL, 1),
(4258147, 614015, 82814, '<td valign="top">Impressive creation</td>', 'Impressive creation', '2007-11-19 13:20:14.000000', NULL, 1),
(4258150, 614462, 37444, '<td valign="top">The key here is her foot off the ground - that implies motion. The background is wonderful and adds so much to the overall image. 10 from me :)</td>', 'The key here is her foot off the ground - that implies motion. The background is wonderful and adds so much to the overall image. 10 from me :)', '2007-11-19 13:20:57.000000', NULL, 1),
(4258152, 614493, 82814, '<td valign="top">Wow.  Really well captured and superb timing.</td>', 'Wow.  Really well captured and superb timing.', '2007-11-19 13:20:57.000000', NULL, 1),
(4258155, 613657, 82814, '<td valign="top">Love this perspective.</td>', 'Love this perspective.', '2007-11-19 13:21:11.000000', NULL, 1),
(4258158, 614572, 37444, '<td valign="top">Here the question is if the dart was caught in flight or suspended and just implies motion.</td>', 'Here the question is if the dart was caught in flight or suspended and just implies motion.', '2007-11-19 13:21:40.000000', NULL, 1),
(4258161, 614562, 82814, '<td valign="top">A really fun idea and nicely executed.</td>', 'A really fun idea and nicely executed.', '2007-11-19 13:22:02.000000', NULL, 1),
(4258167, 614187, 82814, '<td valign="top">brilliant.</td>', 'brilliant.', '2007-11-19 13:22:45.000000', NULL, 1),
(4258168, 614696, 37444, '<td valign="top">The tile is confusing - three? It is possible that the reflection is counted but it is too unclear. Other than that the gull is perfect but having the secong on in focus would have been a bit better. 9</td>', 'The tile is confusing - three? It is possible that the reflection is counted but it is too unclear. Other than that the gull is perfect but having the secong on in focus would have been a bit better. 9', '2007-11-19 13:22:56.000000', NULL, 1),
(4258170, 614721, 37444, '<td valign="top">Of curse, the water drop shot :) The green part hides the water too much though.</td>', 'Of curse, the water drop shot :) The green part hides the water too much though.', '2007-11-19 13:23:45.000000', NULL, 1),
(4258172, 612637, 37444, '<td valign="top">Nicely done though I would prefer to see a longer line of dominoes. 7</td>', 'Nicely done though I would prefer to see a longer line of dominoes. 7', '2007-11-19 13:24:15.000000', NULL, 1),
(4258173, 614453, 23484, '<td valign="top">I really like this shot and I hope you do well with it. I love the processing.  Too bad I can''t vote on it.</td>', 'I really like this shot and I hope you do well with it. I love the processing.  Too bad I can''t vote on it.', '2007-11-19 13:24:25.000000', NULL, 1),
(4258175, 614700, 37444, '<td valign="top">The leaves are nicely caught but the background (people) do what for the image? They seem to be in the way.</td>', 'The leaves are nicely caught but the background (people) do what for the image? They seem to be in the way.', '2007-11-19 13:24:54.000000', NULL, 1),
(4258176, 614054, 23484, '<td valign="top">Nice angle and good capture.</td>', 'Nice angle and good capture.', '2007-11-19 13:24:59.000000', NULL, 1),
