(4258185, 613953, 82814, '<td valign="top">Interesting shot.</td>', 'Interesting shot.', '2007-11-19 13:27:30.000000', NULL, 1),
(4258186, 614657, 37444, '<td valign="top">Oh how perfectly cute! I would just like more headroom - like a portrait orientation. Still a 10 from me :)</td>', 'Oh how perfectly cute! I would just like more headroom - like a portrait orientation. Still a 10 from me :)', '2007-11-19 13:27:33.000000', NULL, 1),
(4258189, 614695, 37444, '<td valign="top">The cat looks asleep  LOL And I suppose the title is his/her name? It is unclear to the viewer.</td>', 'The cat looks asleep  LOL And I suppose the title is his/her name? It is unclear to the viewer.', '2007-11-19 13:28:18.000000', NULL, 1),
(4258190, 613605, 82814, '<td valign="top">Nicely captured.</td>', 'Nicely captured.', '2007-11-19 13:28:42.000000', NULL, 1),
