(4260193, 613752, 49109, '<td valign="top">nice setup, perfect exposure. wish the surface was monochrome to have less refractions in the liquid</td>', 'nice setup, perfect exposure. wish the surface was monochrome to have less refractions in the liquid', '2007-11-20 10:56:55.000000', NULL, 1),
