(4260644, 614672, 82816, '<td valign="top">wow... that''s awesome! (slight motion line, but i think i''ll give it a break considering it is a bullet...) ;-)</td>', 'wow... that''s awesome! (slight motion line, but i think i''ll give it a break considering it is a bullet...) ;-)', '2007-11-20 15:00:40.000000', NULL, 1),
(4260645, 614495, 58691, '<td valign="top">This was a good attempt, but the blue jay is lost in the composition. The colors are good on the bird, but it lighting is harsh and the bird is out of focus and part of the background.</td>', 'This was a good attempt, but the blue jay is lost in the composition. The colors are good on the bird, but it lighting is harsh and the bird is out of focus and part of the background.', '2007-11-20 15:01:08.000000', NULL, 1),
