(4262048, 614722, 36619, '<td valign="top">very sweet shot</td>', 'very sweet shot', '2007-11-21 02:24:09.000000', NULL, 1),
(4262049, 614556, 29906, '<td valign="top">What a nice shot this is. Very well done. 10</td>', 'What a nice shot this is. Very well done. 10', '2007-11-21 02:25:03.000000', NULL, 1),
(4262050, 614543, 29906, '<td valign="top">This brings back memories. Also a great shot.</td>', 'This brings back memories. Also a great shot.', '2007-11-21 02:26:36.000000', NULL, 1),
(4262052, 614688, 36619, '<td valign="top">feels very peace-ful. nice shot</td>', 'feels very peace-ful. nice shot', '2007-11-21 02:27:36.000000', NULL, 1),
(4262054, 613913, 36619, '<td valign="top">just stunning! i want whatever camera you have :)</td>', 'just stunning! i want whatever camera you have :)', '2007-11-21 02:30:09.000000', NULL, 1),
(4262057, 614706, 29906, '<td valign="top">The concept is nice but here are couple of things that would improve this shot:<br/> <br/>1- Eliminating The harsh shadows. This can be accomplished by using an indirect lighting instead of directing the flash straight at the subject.<br/> <br/>2- The door in the background is distracting and makes the shot feel amateurish. <br/> <br/>If it was just a plain wall with no shadows, this would''ve been a winner in my opinion.</td>', 'The concept is nice but here are couple of things that would improve this shot: 1- Eliminating The harsh shadows. This can be accomplished by using an indirect lighting instead of directing the flash straight at the subject. 2- The door in the background is distracting and makes the shot feel amateurish.  If it was just a plain wall with no shadows, this would''ve been a winner in my opinion.', '2007-11-21 02:32:45.000000', NULL, 1),
(4262058, 614670, 29906, '<td valign="top">Clever idea and nice shot.</td>', 'Clever idea and nice shot.', '2007-11-21 02:34:34.000000', NULL, 1),
(4262132, 614047, 35669, '<td valign="top">love it!<br/> <br/>you may enjoy the work of <a href="//www.flickr.com/photos/hughes_leglise/1620467898/" rel="nofollow" target="_blank">Hughes leglise-bataille</a> he does some interesting journalistic work.  Some of which is in the same vein as this image.</td>', 'love it! you may enjoy the work of Hughes leglise-bataille he does some interesting journalistic work.  Some of which is in the same vein as this image.', '2007-11-21 03:47:30.000000', NULL, 1),
(4262231, 614196, 86834, '<td valign="top">I love this. The bird is so elegant. <br/>You capture its movement very well.</td>', 'I love this. The bird is so elegant. You capture its movement very well.', '2007-11-21 06:11:34.000000', NULL, 1),
(4262232, 614493, 86834, '<td valign="top">cool!! seems like a whirlpool</td>', 'cool!! seems like a whirlpool', '2007-11-21 06:12:16.000000', NULL, 1),
(4262331, 613913, 80354, '<td valign="top">That''s completely amazing. The aperture is amazing - so crisp on such a fast object.<br/>The colors on the body are also just... wow. I love this. It strikes me well.</td>', 'That''s completely amazing. The aperture is amazing - so crisp on such a fast object.The colors on the body are also just... wow. I love this. It strikes me well.', '2007-11-21 08:06:31.000000', NULL, 1),
(4262332, 614562, 80354, '<td valign="top">This is VERY nice. I really like this. Mostly because I REALLY understand how fun study breaks can actually be when you''re studying your ass off. =D</td>', 'This is VERY nice. I really like this. Mostly because I REALLY understand how fun study breaks can actually be when you''re studying your ass off. =D', '2007-11-21 08:07:49.000000', NULL, 1),
(4262334, 613117, 80354, '<td valign="top">I love this. What is that?</td>', 'I love this. What is that?', '2007-11-21 08:08:17.000000', NULL, 1),
(4262336, 614563, 80354, '<td valign="top">LMAO! That''s so cute!</td>', 'LMAO! That''s so cute!', '2007-11-21 08:08:59.000000', NULL, 1),
(4262340, 614706, 80354, '<td valign="top">I like the concept, but I''m not diggin'' the background. Plain white would be fine, but that''s sort of off-white and those ridges take away from the concentration of the photo.</td>', 'I like the concept, but I''m not diggin'' the background. Plain white would be fine, but that''s sort of off-white and those ridges take away from the concentration of the photo.', '2007-11-21 08:11:12.000000', NULL, 1),
(4262341, 614673, 80354, '<td valign="top">Disney? haha.</td>', 'Disney? haha.', '2007-11-21 08:11:59.000000', NULL, 1),
(4262343, 613799, 80354, '<td valign="top">Very nice. I love the crispness of the leaves in the corner, with the sun coming through them.</td>', 'Very nice. I love the crispness of the leaves in the corner, with the sun coming through them.', '2007-11-21 08:13:11.000000', NULL, 1),
(4262347, 613598, 80354, '<td valign="top">Haha. This is so cute! Beautiful dog. Is it yours? I love how you you can see the dog''s eyes. This could not only be a water picture, but I could just imagine it as a blizzard around a frazzled dog. =D</td>', 'Haha. This is so cute! Beautiful dog. Is it yours? I love how you you can see the dog''s eyes. This could not only be a water picture, but I could just imagine it as a blizzard around a frazzled dog. =D', '2007-11-21 08:15:15.000000', NULL, 1),
(4262350, 614340, 80354, '<td valign="top">I like this one very much. <br/>I love the way conductors move, how they "talk" to their students and how they can very much look like refs when they''re conducting. =D<br/>You captured it very well.</td>', 'I like this one very much. I love the way conductors move, how they "talk" to their students and how they can very much look like refs when they''re conducting. =DYou captured it very well.', '2007-11-21 08:16:59.000000', NULL, 1),
(4262394, 614717, 81382, '<td valign="top">Interesting being upside down. A relatively high ISO is evident in the colour noise in the background, this could easily have been masked off and eliminated</td>', 'Interesting being upside down. A relatively high ISO is evident in the colour noise in the background, this could easily have been masked off and eliminated', '2007-11-21 08:51:44.000000', NULL, 1),
(4262396, 614533, 81382, '<td valign="top">Fairly noisy and quite soft. I''m guessing you were zoomed in and may have lost apature when doing so and so had to compromise by using a higher ISO. Well composed though, would have been better with just the single bird as the other two don''t conform to the challange and are facing the wrong way</td>', 'Fairly noisy and quite soft. I''m guessing you were zoomed in and may have lost apature when doing so and so had to compromise by using a higher ISO. Well composed though, would have been better with just the single bird as the other two don''t conform to the challange and are facing the wrong way', '2007-11-21 08:53:58.000000', NULL, 1),
(4262418, 614493, 23668, '<td valign="top">very good</td>', 'very good', '2007-11-21 09:07:40.000000', NULL, 1),
(4262505, 614493, 82248, '<td valign="top">very nice</td>', 'very nice', '2007-11-21 09:51:41.000000', NULL, 1),
(4262566, 613485, 78715, '<td valign="top">Amazing</td>', 'Amazing', '2007-11-21 10:30:22.000000', NULL, 1),
(4262656, 614670, 72929, '<td valign="top">Zones suck as bowling balls, I prefer Hammers. But you don''t care about that :) This is a fun photo.</td>', 'Zones suck as bowling balls, I prefer Hammers. But you don''t care about that :) This is a fun photo.', '2007-11-21 11:11:25.000000', NULL, 1),
(4262668, 614067, 72929, '<td valign="top">My first thought when I saw the "stopped motion" challenge was to do an astrophoto. Very appropriate! It''s upside down, you have some coma or spherical abberation on your non-APO scope (or you were imaging in hazy conditions and using a newt, assuming the diffraction spikes are real) and the color balance is a bit on the purple side, but otherwise well done. You have great star colors, good tracking, low noise and you exposed the comet well.</td>', 'My first thought when I saw the "stopped motion" challenge was to do an astrophoto. Very appropriate! It''s upside down, you have some coma or spherical abberation on your non-APO scope (or you were imaging in hazy conditions and using a newt, assuming the diffraction spikes are real) and the color balance is a bit on the purple side, but otherwise well done. You have great star colors, good tracking, low noise and you exposed the comet well.', '2007-11-21 11:14:53.000000', NULL, 1),
(4262675, 614459, 72929, '<td valign="top">Only nitpick is a teeny bit of motion blur on her bottom foot. DOF and lighting are great, and the model''s pose and eye contact are well done. Helps that she is fetching :)</td>', 'Only nitpick is a teeny bit of motion blur on her bottom foot. DOF and lighting are great, and the model''s pose and eye contact are well done. Helps that she is fetching :)', '2007-11-21 11:16:51.000000', NULL, 1),
(4262739, 614575, 58691, '<td valign="top">Excellent capture and processing. What I really like are the additional elements in the scene - the bride/groom, the onlookers, the band and the photographer - all compliment the setting. Outstanding.</td>', 'Excellent capture and processing. What I really like are the additional elements in the scene - the bride/groom, the onlookers, the band and the photographer - all compliment the setting. Outstanding.', '2007-11-21 11:39:51.000000', NULL, 1),
(4262747, 613354, 58691, '<td valign="top">The separation of the flame from the wick is what draws my eye in and makes for a dramatic shot. The smoke doesn''t seem like it belongs to the flame, but that isn''t anything major. Nice shot.</td>', 'The separation of the flame from the wick is what draws my eye in and makes for a dramatic shot. The smoke doesn''t seem like it belongs to the flame, but that isn''t anything major. Nice shot.', '2007-11-21 11:43:04.000000', NULL, 1),
(4262753, 614533, 58691, '<td valign="top">This looks like originally it was a good capture - stopped motion, good composition, nice reflection - but it looks like it was over sharpened. I see a lot of pixel scarring.</td>', 'This looks like originally it was a good capture - stopped motion, good composition, nice reflection - but it looks like it was over sharpened. I see a lot of pixel scarring.', '2007-11-21 11:44:39.000000', NULL, 1),
(4262758, 612566, 58691, '<td valign="top">This has the makings of a good shot, but since this was an advanced challenge, cloning out the jeans in the background and that white spot on the back of the chair/couch would''ve helped a lot.</td>', 'This has the makings of a good shot, but since this was an advanced challenge, cloning out the jeans in the background and that white spot on the back of the chair/couch would''ve helped a lot.', '2007-11-21 11:47:13.000000', NULL, 1),
(4262763, 614718, 58691, '<td valign="top">The lighting hurts this shot as the shadows are too heavy on the lower thirds. It would''ve been good to get the tiger looking up. Its eyes would give more personality to the image.</td>', 'The lighting hurts this shot as the shadows are too heavy on the lower thirds. It would''ve been good to get the tiger looking up. Its eyes would give more personality to the image.', '2007-11-21 11:49:22.000000', NULL, 1),
(4262771, 614187, 58691, '<td valign="top">This is one of the better liquid drop shots as the droplet is lit differently from the base and there is a distinct, singular reflection and an identifyable ellispe. Well done.</td>', 'This is one of the better liquid drop shots as the droplet is lit differently from the base and there is a distinct, singular reflection and an identifyable ellispe. Well done.', '2007-11-21 11:52:00.000000', NULL, 1),
(4262774, 614724, 58691, '<td valign="top">This is a different twist on the numerous liquid drop shots in this challenge. I like the tall column of milk, but the bottle seems disconnected from the splash. Maybe some condensation on the bottle or more milk spilled on the base.  Decent capture, though.</td>', 'This is a different twist on the numerous liquid drop shots in this challenge. I like the tall column of milk, but the bottle seems disconnected from the splash. Maybe some condensation on the bottle or more milk spilled on the base.  Decent capture, though.', '2007-11-21 11:54:35.000000', NULL, 1),
(4262776, 614422, 58691, '<td valign="top">This looks noisy and over-processed - lighten up on the sharpness and soften the shot.</td>', 'This looks noisy and over-processed - lighten up on the sharpness and soften the shot.', '2007-11-21 11:55:50.000000', NULL, 1),
(4262779, 614671, 58691, '<td valign="top">The background takes focus away from the dice and is overpowering the shot. A solid background would''ve helped a lot. Also, the light source is too weak.</td>', 'The background takes focus away from the dice and is overpowering the shot. A solid background would''ve helped a lot. Also, the light source is too weak.', '2007-11-21 11:57:15.000000', NULL, 1),
(4262785, 614149, 58691, '<td valign="top">Outstanding shot. Great job of locking the focus on the fly line. Lighting, sharpness, foreground/background separation - all very well done. This is excellent.</td>', 'Outstanding shot. Great job of locking the focus on the fly line. Lighting, sharpness, foreground/background separation - all very well done. This is excellent.', '2007-11-21 11:58:44.000000', NULL, 1),
(4262787, 613892, 58691, '<td valign="top">This is a good clear capture but there isn''t any focal point that draws in the eye.</td>', 'This is a good clear capture but there isn''t any focal point that draws in the eye.', '2007-11-21 12:00:39.000000', NULL, 1),
(4262789, 614221, 58691, '<td valign="top">I like the highlights in this shot, but the audience/background is a bit distracting. This was an advanced challenge, so you could''ve cloned them out.</td>', 'I like the highlights in this shot, but the audience/background is a bit distracting. This was an advanced challenge, so you could''ve cloned them out.', '2007-11-21 12:01:57.000000', NULL, 1),
(4262971, 613765, 58691, '<td valign="top">This is one of the better exploding water balloon shots as the balloon is not obstructed by the waterball, but the white background doesn''t provide many contrast with the water and the water is hard to make out. There is an odd coloration on the hand that could''ve been leveled out. With that said, the good still outweighs the bad and this is a quality shot.</td>', 'This is one of the better exploding water balloon shots as the balloon is not obstructed by the waterball, but the white background doesn''t provide many contrast with the water and the water is hard to make out. There is an odd coloration on the hand that could''ve been leveled out. With that said, the good still outweighs the bad and this is a quality shot.', '2007-11-21 13:42:28.000000', NULL, 1),
(4262978, 614383, 58691, '<td valign="top">Well done. There were a lot of bird images submitted for this challenge, but this may be the best on yet. You were at an excellent angle to catch this and the focus and DOF are spot on. I love the green hue underneath the wings. Well captured.</td>', 'Well done. There were a lot of bird images submitted for this challenge, but this may be the best on yet. You were at an excellent angle to catch this and the focus and DOF are spot on. I love the green hue underneath the wings. Well captured.', '2007-11-21 13:45:33.000000', NULL, 1),
(4262999, 614394, 58691, '<td valign="top">If it weren''t for the title, I wouldn''t know there was ice in the glass. The fluid totally absorbs the outline of the cubes This probably would''ve worked better with the absence of water.</td>', 'If it weren''t for the title, I wouldn''t know there was ice in the glass. The fluid totally absorbs the outline of the cubes This probably would''ve worked better with the absence of water.', '2007-11-21 13:50:07.000000', NULL, 1),
(4263006, 614717, 58691, '<td valign="top">Good concept and I like how the water distorts the die. The focus is rather soft, though.</td>', 'Good concept and I like how the water distorts the die. The focus is rather soft, though.', '2007-11-21 13:51:41.000000', NULL, 1),
(4263033, 614667, 58691, '<td valign="top">This is cute. It would be better if the droplets didn''t obscure her smile, but other than that, this is quite nice.</td>', 'This is cute. It would be better if the droplets didn''t obscure her smile, but other than that, this is quite nice.', '2007-11-21 13:59:55.000000', NULL, 1),
(4263043, 614453, 58691, '<td valign="top">This almost looks like an impressionist piece... I love the building and its broken/crooked window. Nice.</td>', 'This almost looks like an impressionist piece... I love the building and its broken/crooked window. Nice.', '2007-11-21 14:02:58.000000', NULL, 1),
(4263054, 614144, 66348, '<td valign="top">Great silhouette. I like the colors and the composition is nice.</td>', 'Great silhouette. I like the colors and the composition is nice.', '2007-11-21 14:06:42.000000', NULL, 1),
(4263056, 613604, 58691, '<td valign="top">Well done. I think the balls are in alignment and spaced so as not to obscure the subject''s face. Great choice on the black shirt and background. Focus and the crop are dead on. Outstanding.</td>', 'Well done. I think the balls are in alignment and spaced so as not to obscure the subject''s face. Great choice on the black shirt and background. Focus and the crop are dead on. Outstanding.', '2007-11-21 14:07:02.000000', NULL, 1),
(4263065, 614649, 58691, '<td valign="top">I like the silhouette effect of this. Well done.</td>', 'I like the silhouette effect of this. Well done.', '2007-11-21 14:09:27.000000', NULL, 1),
(4263071, 614622, 58691, '<td valign="top">Beautiful! Excellent timing to the horse fully air born.</td>', 'Beautiful! Excellent timing to the horse fully air born.', '2007-11-21 14:10:48.000000', NULL, 1),
(4263077, 614541, 66348, '<td valign="top">Great colors and composition. Very difficult to catch with the lighting I''m sure you had, so nice work.</td>', 'Great colors and composition. Very difficult to catch with the lighting I''m sure you had, so nice work.', '2007-11-21 14:12:06.000000', NULL, 1),
(4263080, 614176, 66348, '<td valign="top">Great lighting and catch. Composition is great also. Little noisy in the wing area but I am sure that was due to the higher ISO. Nice work.</td>', 'Great lighting and catch. Composition is great also. Little noisy in the wing area but I am sure that was due to the higher ISO. Nice work.', '2007-11-21 14:12:51.000000', NULL, 1),
(4263084, 614085, 66348, '<td valign="top">Sweet capture, great composition and nice idea.</td>', 'Sweet capture, great composition and nice idea.', '2007-11-21 14:13:19.000000', NULL, 1),
(4263085, 614459, 66348, '<td valign="top">Great pose. Love the lighting and the composition. Nice work.</td>', 'Great pose. Love the lighting and the composition. Nice work.', '2007-11-21 14:14:01.000000', NULL, 1),
(4263090, 614134, 66348, '<td valign="top">Love this shot, being from CA I love all surf shots. Great capture, with great clarity and sharpness. Stop motion is perfect. Nice job.</td>', 'Love this shot, being from CA I love all surf shots. Great capture, with great clarity and sharpness. Stop motion is perfect. Nice job.', '2007-11-21 14:14:48.000000', NULL, 1),
(4263091, 613605, 58691, '<td valign="top">This is a good capture. Well done. I wish there was more sports photography on DPC.</td>', 'This is a good capture. Well done. I wish there was more sports photography on DPC.', '2007-11-21 14:14:50.000000', NULL, 1),
(4263094, 612859, 66348, '<td valign="top">Great angle, and composition. Colors are great also. Nice work.</td>', 'Great angle, and composition. Colors are great also. Nice work.', '2007-11-21 14:15:32.000000', NULL, 1),
(4263097, 614674, 66348, '<td valign="top">Great colors and composition. Nice job.</td>', 'Great colors and composition. Nice job.', '2007-11-21 14:15:54.000000', NULL, 1),
(4263100, 613752, 66348, '<td valign="top">Great catch. Love the composition and idea. Perfect lighting. Nice work.</td>', 'Great catch. Love the composition and idea. Perfect lighting. Nice work.', '2007-11-21 14:16:16.000000', NULL, 1),
(4263102, 614493, 66348, '<td valign="top">Great capture. Although this is done a lot you have shot it spot on, with great composition and lighting. Nice job.</td>', 'Great capture. Although this is done a lot you have shot it spot on, with great composition and lighting. Nice job.', '2007-11-21 14:17:04.000000', NULL, 1),
(4263106, 614661, 66348, '<td valign="top">Great editing in your shot. I like how it looks as if he is just floatin about checkin out the world below. Nice work.</td>', 'Great editing in your shot. I like how it looks as if he is just floatin about checkin out the world below. Nice work.', '2007-11-21 14:18:06.000000', NULL, 1),
(4263109, 614709, 66348, '<td valign="top">Beautiful colors in the bird. Also really like your composition. Nice job.</td>', 'Beautiful colors in the bird. Also really like your composition. Nice job.', '2007-11-21 14:18:43.000000', NULL, 1),
(4263110, 614721, 58691, '<td valign="top">The RGB base in this shot detracts from and hides the water spout. Nice capture on the spout and good focus.</td>', 'The RGB base in this shot detracts from and hides the water spout. Nice capture on the spout and good focus.', '2007-11-21 14:19:28.000000', NULL, 1),
(4263111, 614015, 66348, '<td valign="top">Thats just sweet. Great shot, and idea. Nice composition and the lighting is spot on. Nice work.</td>', 'Thats just sweet. Great shot, and idea. Nice composition and the lighting is spot on. Nice work.', '2007-11-21 14:19:30.000000', NULL, 1),
(4263115, 614556, 66348, '<td valign="top">I really like the tone mapped look. This is really a sweet shot. I like the composition and angle in this shot. Well done.</td>', 'I really like the tone mapped look. This is really a sweet shot. I like the composition and angle in this shot. Well done.', '2007-11-21 14:20:16.000000', NULL, 1),
(4263118, 612956, 66348, '<td valign="top">Great pose. Nice lighting and sweet idea. I love the shadowed look with the light on the face. Almost like he is painted on the wall. Nice work.</td>', 'Great pose. Nice lighting and sweet idea. I love the shadowed look with the light on the face. Almost like he is painted on the wall. Nice work.', '2007-11-21 14:21:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4263120, 614387, 66348, '<td valign="top">I love the pure feel to this shot. Great composition and lighting. The cloud really adds the shot, nice work.</td>', 'I love the pure feel to this shot. Great composition and lighting. The cloud really adds the shot, nice work.', '2007-11-21 14:21:39.000000', NULL, 1),
(4263123, 614696, 66348, '<td valign="top">So the third is in the reflection right? Nice composition and DOF. Well done.</td>', 'So the third is in the reflection right? Nice composition and DOF. Well done.', '2007-11-21 14:22:31.000000', NULL, 1),
(4263124, 614149, 66348, '<td valign="top">Great composition and idea. The stopped motion is great and I really like the tones in your shot. Nice work.</td>', 'Great composition and idea. The stopped motion is great and I really like the tones in your shot. Nice work.', '2007-11-21 14:23:11.000000', NULL, 1),
(4263127, 613605, 66348, '<td valign="top">Great capture, the water is really sweet coming off of her body, nice composition and idea.</td>', 'Great capture, the water is really sweet coming off of her body, nice composition and idea.', '2007-11-21 14:23:53.000000', NULL, 1),
(4263132, 614187, 66348, '<td valign="top">I love the brown in this shot, the drip is perfect, and the border is pretty damn sweet. The coffee in this shot seems as if a warm melted bowl of hershey chocolate. Lovely image.</td>', 'I love the brown in this shot, the drip is perfect, and the border is pretty damn sweet. The coffee in this shot seems as if a warm melted bowl of hershey chocolate. Lovely image.', '2007-11-21 14:25:27.000000', NULL, 1),
