(4263139, 614465, 66348, '<td valign="top">Great composition and capture. Love the DOF also. Nice work.</td>', 'Great composition and capture. Love the DOF also. Nice work.', '2007-11-21 14:26:34.000000', NULL, 1),
(4263143, 614673, 66348, '<td valign="top">Thats just sweet. Great capture! That wasn''t you in the car was it?</td>', 'Thats just sweet. Great capture! That wasn''t you in the car was it?', '2007-11-21 14:27:01.000000', NULL, 1),
(4263147, 614493, 85028, '<td valign="top">Super work.</td>', 'Super work.', '2007-11-21 14:27:23.000000', NULL, 1),
