(4264572, 613752, 58691, '<td valign="top">The blown out background adds a necessary contrast to the bottle and the glass. The focus is excellent and the column of liquid is precise. Very good.</td>', 'The blown out background adds a necessary contrast to the bottle and the glass. The focus is excellent and the column of liquid is precise. Very good.', '2007-11-22 12:20:08.000000', NULL, 1),
(4264575, 613383, 58691, '<td valign="top">This is a unique shot with a double exposure. I like how the bulb pieces look like the petals of a flower.</td>', 'This is a unique shot with a double exposure. I like how the bulb pieces look like the petals of a flower.', '2007-11-22 12:21:38.000000', NULL, 1),
(4264578, 614541, 58691, '<td valign="top">Brilliant capture. The lighting is perfect and the perspective really draws in the eye. well done.</td>', 'Brilliant capture. The lighting is perfect and the perspective really draws in the eye. well done.', '2007-11-22 12:23:26.000000', NULL, 1),
(4264588, 614559, 58691, '<td valign="top">The red and blue anomalies in this shot and the fact that the water is no longer globular in shape hurts this image - compared to the others in this challenge. On its own, the contrast and focus are good, but the final result is that it is a bit too chaotic.</td>', 'The red and blue anomalies in this shot and the fact that the water is no longer globular in shape hurts this image - compared to the others in this challenge. On its own, the contrast and focus are good, but the final result is that it is a bit too chaotic.', '2007-11-22 12:32:01.000000', NULL, 1),
