(4267521, 613752, 43442, '<td valign="top">very nice</td>', 'very nice', '2007-11-24 22:27:23.000000', NULL, 1),
(4267652, 613240, 19936, '<td valign="top">Good concept but the motion is blurred and the shot is very noisy. If it were tack sharp it would have worked better for me.  Good luck.</td>', 'Good concept but the motion is blurred and the shot is very noisy. If it were tack sharp it would have worked better for me.  Good luck.', '2007-11-25 00:48:02.000000', NULL, 1),
(4267655, 614674, 19936, '<td valign="top">You got the motion stopped and picked a decent subject but the color looks way off to me.  I got a comment once about black borders fencing in moving subjects. I took it as good advice and I think it applies here or at least not such a bold border.  Anyway, keep clicking and good luck.</td>', 'You got the motion stopped and picked a decent subject but the color looks way off to me.  I got a comment once about black borders fencing in moving subjects. I took it as good advice and I think it applies here or at least not such a bold border.  Anyway, keep clicking and good luck.', '2007-11-25 00:52:01.000000', NULL, 1),
(4267663, 613913, 19936, '<td valign="top">Nice stop!  I wanted to shot a hummer but the only one who winters over (Annas) would not cooperate with me when the light was decent.  Anyway, great shot.  Only complaint I would have is that it is a bit dark against the dark background. But that is being picky.</td>', 'Nice stop!  I wanted to shot a hummer but the only one who winters over (Annas) would not cooperate with me when the light was decent.  Anyway, great shot.  Only complaint I would have is that it is a bit dark against the dark background. But that is being picky.', '2007-11-25 01:01:05.000000', NULL, 1),
(4267678, 614661, 83706, '<td valign="top">great combination of colors and love the composition</td>', 'great combination of colors and love the composition', '2007-11-25 01:33:09.000000', NULL, 1),
