(4269240, 614493, 64929, '<td valign="top">Forever your fan!  Brilliant! Congrats~<br/>*Elizabeth*</td>', 'Forever your fan!  Brilliant! Congrats~*Elizabeth*', '2007-11-26 08:38:54.000000', NULL, 0),
(4269246, 613913, 64929, '<td valign="top">Never a doubt for the Blue!  Unbelievably beautiful - Congrats!</td>', 'Never a doubt for the Blue!  Unbelievably beautiful - Congrats!', '2007-11-26 08:41:09.000000', NULL, 0),
(4269277, 614445, 66384, '<td valign="top">The little wake in the back, like a motor boat, makes me laugh. The splash in front is beautifully smooth against the choppy water. The posture of the bird is lovely. I really like this shot and can''t imagine why it placed so far down in the pack.</td>', 'The little wake in the back, like a motor boat, makes me laugh. The splash in front is beautifully smooth against the choppy water. The posture of the bird is lovely. I really like this shot and can''t imagine why it placed so far down in the pack.', '2007-11-26 09:01:18.000000', NULL, 0),
(4269304, 613989, 66384, '<td valign="top">I really like this shot. I gave it a 7 because of the beauty of it, but wasn''t sure what action had been stopped.<br/> <br/>P.S. My husband said it''s as if the little brush tail painted the picture. Perhaps that was your intention, which I missed. Brilliant.<br/><br/><i>Message edited by author 2007-11-26 09:19:21.</i></td>', 'I really like this shot. I gave it a 7 because of the beauty of it, but wasn''t sure what action had been stopped. P.S. My husband said it''s as if the little brush tail painted the picture. Perhaps that was your intention, which I missed. Brilliant.', '2007-11-26 09:08:55.000000', '2007-11-26 09:19:21.000000', 0),
(4269331, 614459, 42869, '<td valign="top">I''m really surprised this didn''t make the front page.  I love the post and the stopped action.  Great shot.</td>', 'I''m really surprised this didn''t make the front page.  I love the post and the stopped action.  Great shot.', '2007-11-26 09:18:23.000000', NULL, 0);
